(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"vector":{"h":"WHAT YOU ARE LOOKING AT","t":"Here is one vector **v**: an **arrow from the origin**. Think of it as a direction and a length."},"scale-vector":{"h":"SCALING STRETCHES OR FLIPS IT","t":"Multiplying by a number scales the arrow: **2v is twice as long**, and a **negative number flips** it."},"combine-vectors":{"h":"COMBINE TWO VECTORS","t":"With a second vector **w**, we can build **a·v + b·w**: scale each one, then add them."},"span-line":{"h":"ONE VECTOR SPANS A LINE","t":"All the scaled copies of a single vector lie on **one line through the origin**. That line is its **span**."},"span-plane":{"h":"TWO INDEPENDENT VECTORS SPAN THE PLANE","t":"If v and w do not point along the same line, their combinations reach **every point in the plane**."},"subspace":{"h":"A SUBSPACE IS A FLAT SPACE THROUGH THE ORIGIN","t":"The line is a **subspace** of the plane: it contains the origin, and adding or scaling its vectors **never leaves it**."},"ml-connection":{"h":"TAKEAWAY","t":"Real data often sits **close to a line or plane inside a bigger space**. Finding it lets us describe the data with **fewer numbers**."}};
  // ── scene ──
  var steps = [
    { id: "vector", label: "A vector is an arrow from the origin", caption: "Here is one vector v. Think of it as a direction and a length." },
    { id: "scale-vector", label: "Scaling stretches or flips it", caption: "Multiplying by a number scales the arrow: 2v is twice as long, and a negative number flips it." },
    { id: "combine-vectors", label: "Combine two vectors", caption: "With a second vector w, we can build a·v + b·w: scale each one, then add them." },
    { id: "span-line", label: "One vector spans a line", caption: "All the scaled copies of a single vector lie on one line through the origin. That line is its span." },
    { id: "span-plane", label: "Two independent vectors span the plane", caption: "If v and w do not point along the same line, their combinations reach every point in the plane." },
    { id: "subspace", label: "A subspace is a flat space through the origin", caption: "The line is a subspace of the plane: it contains the origin, and adding or scaling its vectors never leaves it." },
    { id: "ml-connection", label: "Data often lives near a subspace", caption: "Real data often sits close to a line or plane inside a bigger space. Finding it lets us describe the data with fewer numbers." }
  ];

  var P = makePlane(320, 190, 34);
  var V = [2, 1];
  var W = [-1, 2];

  var tint = el("rect", { x: 14, y: 14, width: 612, height: 332, rx: 10, class: "fillA", opacity: 0 }, svg);
  axes(svg, P, 9, 5.2);

  var spanLine = el("line", { x1: P.x(-7), y1: P.y(-3.5), x2: P.x(7), y2: P.y(3.5), stroke: "#1db584", "stroke-width": 3, opacity: 0 }, svg);

  var gridDots = el("g", { opacity: 0 }, svg);
  [-1.5, -0.75, 0, 0.75, 1.5].forEach(function (a) {
    [-1.5, -0.75, 0, 0.75, 1.5].forEach(function (b) {
      el("circle", { cx: P.x(a * V[0] + b * W[0]), cy: P.y(a * V[1] + b * W[1]), r: 3.5, fill: "#c9dccf" }, gridDots);
    });
  });

  var ghost2 = arrow(svg, "y", 2.5);
  ghost2.setAttribute("stroke-dasharray", "5 4");
  setLine(ghost2, P.x(0), P.y(0), P.x(2 * V[0]), P.y(2 * V[1]));
  var ghostNeg = arrow(svg, "r", 2.5);
  ghostNeg.setAttribute("stroke-dasharray", "5 4");
  setLine(ghostNeg, P.x(0), P.y(0), P.x(-V[0]), P.y(-V[1]));
  var lab2 = txt(svg, P.x(2 * V[0]) + 8, P.y(2 * V[1]) - 6, "lbl lbl-y", "2v");
  var labNeg = txt(svg, P.x(-V[0]) - 24, P.y(-V[1]) + 16, "lbl lbl-r", "−v");

  var arrV = arrow(svg, "b", 3.5);
  setLine(arrV, P.x(0), P.y(0), P.x(V[0]), P.y(V[1]));
  var labV = txt(svg, P.x(V[0]) + 8, P.y(V[1]) + 14, "lbl lbl-b", "v");
  var arrW = arrow(svg, "p", 3.5);
  setLine(arrW, P.x(0), P.y(0), P.x(W[0]), P.y(W[1]));
  var labW = txt(svg, P.x(W[0]) - 16, P.y(W[1]) - 6, "lbl lbl-p", "w");

  // a·v + b·w with a = 1.5, b = 1
  var A1 = 1.5, B1 = 1;
  var comb = [A1 * V[0] + B1 * W[0], A1 * V[1] + B1 * W[1]];
  var scaledV = arrow(svg, "b", 2.5);
  scaledV.setAttribute("stroke-dasharray", "5 4");
  setLine(scaledV, P.x(0), P.y(0), P.x(1.5 * V[0]), P.y(1.5 * V[1]));
  var scaledVLab = txt(svg, P.x(1.5 * V[0]) + 8, P.y(1.5 * V[1]) + 16, "lbl lbl-b", "1.5·v");
  var par1 = el("line", { class: "dash", stroke: "#38bdf8", "stroke-width": 1.5 }, svg);
  setLine(par1, P.x(A1 * V[0]), P.y(A1 * V[1]), P.x(comb[0]), P.y(comb[1]));
  var par2 = el("line", { class: "dash", stroke: "#f472b6", "stroke-width": 1.5 }, svg);
  setLine(par2, P.x(B1 * W[0]), P.y(B1 * W[1]), P.x(comb[0]), P.y(comb[1]));
  var combDot = el("circle", { cx: P.x(comb[0]), cy: P.y(comb[1]), r: 6, fill: "#e2b44a" }, svg);
  var combLab = txt(svg, P.x(comb[0]) + 12, P.y(comb[1]) + 4, "lbl lbl-y", "1.5·v + 1·w");

  var origin = el("circle", { cx: P.x(0), cy: P.y(0), r: 5, fill: "#e6f5ec" }, svg);
  var originLab = txt(svg, P.x(0) + 8, P.y(0) + 18, "note", "origin (0)");
  var subLab = txt(svg, 40, 40, "lbl lbl-g", "", "start");
  var subNote = txt(svg, 40, 58, "note", "", "start");

  // Data points near the line (last step).
  var cloud = el("g", { opacity: 0 }, svg);
  for (var t = -3; t <= 3.01; t += 0.5) {
    var off = 0.35 * Math.sin(t * 5.3 + 1);
    var nx = -V[1], ny = V[0];
    var norm = Math.sqrt(nx * nx + ny * ny);
    el("circle", { cx: P.x(2 * t + (nx / norm) * off), cy: P.y(t + (ny / norm) * off), r: 5, fill: "#f472b6" }, cloud);
  }

  function render(index, id) {
    var all = [tint, spanLine, gridDots, ghost2, ghostNeg, lab2, labNeg, arrV, labV, arrW, labW, par1, par2, combDot, combLab, origin, originLab, cloud, scaledV, scaledVLab];
    all.forEach(function (n) { show(n, false); });
    subLab.textContent = "";
    subNote.textContent = "";
    show(origin, true);
    show(originLab, true);

    if (id === "vector") {
      show(arrV, true); show(labV, true);
    } else if (id === "scale-vector") {
      show(arrV, true); show(labV, true); show(ghost2, true); show(lab2, true); show(ghostNeg, true); show(labNeg, true);
    } else if (id === "combine-vectors") {
      show(arrV, true); show(labV, true); show(arrW, true); show(labW, true);
      show(par1, true); show(par2, true); show(combDot, true); show(combLab, true); show(scaledV, true); show(scaledVLab, true);
    } else if (id === "span-line") {
      show(spanLine, true); show(arrV, true); show(labV, true);
      subLab.textContent = "span of v = a line";
    } else if (id === "span-plane") {
      show(gridDots, true); show(arrV, true); show(labV, true); show(arrW, true); show(labW, true);
      subLab.textContent = "span of v and w = the whole plane";
    } else if (id === "subspace") {
      show(tint, true); show(spanLine, true); show(arrV, true); show(labV, true);
      subLab.textContent = "subspace: a line through the origin";
      subNote.textContent = "inside the plane; it always contains 0";
    } else {
      show(spanLine, true); show(cloud, true);
      subLab.textContent = "data close to a line";
      subNote.textContent = "describe each point by one number instead of two";
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
